def generate_fortunes(n, a, b):
    fortunes = [0] * n
    current_max = 0
    oh_count = 0
    wow_count = 0

    for i in range(n):
        if i < a + b:
            if i < a:
                current_max += 1
                fortunes[i] = current_max
                oh_count += 1
            else:
                current_max += 1
                fortunes[i] = current_max
                wow_count += 1
        else:
            if oh_count < a:
                current_max += 1
                fortunes[i] = current_max
                oh_count += 1
            else:
                current_max += 1
                fortunes[i] = current_max
                wow_count += 1

    if oh_count != a or wow_count != b:
        return -1

    return fortunes

# Read input
n, a, b = map(int, input().split())

# Generate and output the sequence
result = generate_fortunes(n, a, b)
if result == -1:
    print(-1)
else:
    print(' '.join(map(str, result)))
